<?php require_once __DIR__.'/../includes/functions.php'; $uuid=$_GET['uuid']??''; $user=null; foreach(list_users() as $x){if(strtolower((string)($x['updateUuid']??''))===strtolower((string)$uuid)){$user=$x;break;}} if(!$user)json_response(['error'=>'UUID não encontrado'],404); $c=user_config($user); $uuid=ensure_uuid($user); json_response(['uuid'=>$uuid,'version'=>(string)$c['Version'],'Update'=>uuid_resource($uuid,'config'),'AppUpdate'=>uuid_resource($uuid,'appupdate'),'SmsUpdate'=>uuid_resource($uuid,'sms'),'ThemeUpdate'=>uuid_resource($uuid,'theme'),'config'=>uuid_resource($uuid,'config'),'appupdate'=>uuid_resource($uuid,'appupdate'),'sms'=>uuid_resource($uuid,'sms'),'theme'=>uuid_resource($uuid,'theme')]);
